WITH matched_keys AS (SELECT id, city FROM customers EXCEPT SELECT id, city FROM customers WHERE signup_date BETWEEN '2024-05-29' AND '2025-10-01'), kept_rows AS (SELECT s.* FROM customers s INNER JOIN matched_keys k ON s.id = k.id AND s.city = k.city) SELECT city, COUNT(*) FILTER (WHERE country = 'TH') AS th_rows, COUNT(*) FILTER (WHERE city = 'Tokyo') AS tokyo_rows FROM kept_rows GROUP BY city ORDER BY tokyo_rows;
